<template><view class="page"><view class="card"><input v-model="form.gender" placeholder="性别"/><input v-model="tags" placeholder="慢病标签，逗号分隔"/><button class="primary" @click="save">保存</button><button @click="logout">退出登录</button></view></view></template>
<script setup>import{ref,onMounted}from'vue';import{api}from'../../api';const form=ref({gender:'',timezone:'Asia/Shanghai',disease_tags:[]});const tags=ref('');onMounted(async()=>{form.value=await api.me();tags.value=(form.value.disease_tags||[]).join(',')});async function save(){await api.updateMe({...form.value,disease_tags:tags.value.split(',').map(x=>x.trim()).filter(Boolean)})}async function logout(){try{await api.logout()}finally{uni.removeStorageSync('access_token');uni.reLaunch({url:'/pages/login/login'})}}</script>
